def write_test_file(path: Path, content: str) -> None:
    """Write a test file, creating parent directories as needed."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


def generate_tests(up_to: int | None) -> None:
    """Generate Jest test files for the requested milestones."""
    for milestone, files in MILESTONE_TESTS.items():
        if up_to is not None and milestone > up_to:
            continue
        for filename, content in files:
            test_path = TESTS_DIR / filename
            write_test_file(test_path, content)


def ensure_node_modules() -> None:
    """Run `npm install` if node_modules directory is missing."""
    node_modules = PROJECT_ROOT / "node_modules"
    if node_modules.is_dir():
        return
    print("🔧 node_modules not found – running `npm install`...")
    try:
        subprocess.run(
            ["npm", "install"],
            cwd=PROJECT_ROOT,
            check=True,
            stdout=sys.stdout,
            stderr=sys.stderr,
            timeout=600,
        )
    except subprocess.CalledProcessError as exc:
        print(f"❌ npm install failed (exit code {exc.returncode})")
        sys.exit(1)


def run_jest(up_to: int | None) -> int:
    """Execute Jest with optional milestone filter."""
    # Build the -t pattern if a limit is set
    jest_args = ["npx", "jest", "--ci", "__tests__/acceptance"]
    if up_to is not None:
        allowed = "|".join(f"M{i}" for i in range(1, up_to + 1))
        pattern = f"^({allowed}): "
        jest_args.extend(["-t", pattern])
    print(f"🚀 Running Jest with args: {' '.join(jest_args)}")
    result = subprocess.run(
        jest_args,
        cwd=PROJECT_ROOT,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        timeout=600,
    )
    print(result.stdout)
    return result.returncode


def main() -> None:
    # Determine the milestone limit from the environment
    milestone_env = os.getenv("ACCEPTANCE_MILESTONE")
    milestone_limit: int | None = None
    if milestone_env:
        try:
            milestone_limit = int(milestone_env)
            if milestone_limit < 1:
                raise ValueError()
        except ValueError:
            print(
                "⚠️  Invalid ACCEPTANCE_MILESTONE value – must be a positive integer."
            )
            sys.exit(2)

    # Step 1: generate the Jest test files
    generate_tests(milestone_limit)

    # Step 2: make sure dependencies are installed
    ensure_node_modules()

    # Step 3: run Jest
    exit_code = run_jest(milestone_limit)

    if exit_code == 0:
        print("✅ All acceptance tests passed.")
    else:
        print(f"❌ Acceptance tests failed (exit code {exit_code}).")
    sys.exit(exit_code)


if __name__ == "__main__":
    main()
