}
"}

{"path": "src/screens/DashboardScreen.tsx", "content": "import React, { useEffect, useState } from 'react';
import { ActivityIndicator, Snackbar } from 'react-native-paper';
import { FlatList, View } from 'react-native';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { EmptyState, PrimaryButton, Screen, SummaryCard } from '../components/ui';
import { getStore } from '../lib/storage';
import { Receipt } from '../lib/models';
import { getAllReceipts } from '../lib/receiptStore';
import { computeTotals } from '../lib/finance';
import ReceiptCard from '../components/ui/ReceiptCard';

export default function DashboardScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [loading, setLoading] = useState(true);
  const [receipts, setReceipts] = useState<Receipt[]>([]);
  const [snack, setSnack] = useState<string>('');

  const load = async () => {
    setLoading(true);
    const recs = await getAllReceipts(getStore());
    setReceipts(recs);
    setLoading(false);
  };

  useEffect(() => {
    const unsubscribe = navigation.addListener('focus', load);
    return unsubscribe;
  }, [navigation]);

  if (loading) {
    return <ActivityIndicator style={{ flex: 1 }} accessibilityLabel="Loading" />;
  }

  const totals = computeTotals(receipts);

  const empty = receipts.length === 0;

  return (
    <Screen title="Dashboard" wide>
      {empty ? (
        <EmptyState
          icon="inbox-outline"
          title="Nothing here yet"
          body="Add a receipt or mileage entry to start tracking your finances."
          actionLabel="Add receipt"
          onAction={() => navigation.navigate('ReceiptEntry')}
        />
      ) : (
        <View style={{ gap: 16 }}>
          <View style={{ flexDirection: 'row', gap: 8, flexWrap: 'wrap' }}>
            <SummaryCard label="Income" value={`$${totals.income.toFixed(2)}`} />
            <SummaryCard label="Expenses" value={`$${totals.expenses.toFixed(2)}`} />
          </View>
          <FlatList
            data={receipts.slice(0, 5)}
            keyExtractor={(item) => item.id}
            renderItem={({ item }) => <ReceiptCard receipt={item} />}
          />
        </View>
      )}
      <Snackbar visible={!!snack} onDismiss={() => setSnack('')} duration={3000}>
        {snack}
      </Snackbar>
    </Screen>
  );
}
"}

{"path": "src/lib/finance.ts", "content": "// Finance calculation helpers.
import type { Receipt } from './models';

export interface Totals {
  income: number;
  expenses: number;
  // Additional fields (mileage, tax) can be added later.
}

/** Compute total income and expenses from a list of receipts. */
export function computeTotals(receipts: Receipt[]): Totals {
  let income = 0;
  let expenses = 0;
  for (const r of receipts) {
    if (r.type === 'income') {
      income += r.amount;
    } else {
      expenses += r.amount;
    }
  }
  return { income, expenses };
}
"}

{"path":"src/lib/policy.ts","content":"// Terms of Use / Privacy Policy gate. Bump POLICY_VERSION whenever the text changes: everyone must accept again.
import type { Store } from './storage';

export const POLICY_VERSION = '1';
const KEY = 'policy.acceptance';

export interface PolicyAcceptance {
  version: string;
  acceptedAt: string; // ISO date-time
}

export async function getPolicyAcceptance(store: Store): Promise<PolicyAcceptance | null> {
  return store.get<PolicyAcceptance>(KEY);
}

export function policyAccepted(acceptance: PolicyAcceptance | null): boolean {
  return acceptance?.version === POLICY_VERSION;
}

export async function acceptPolicy(store: Store, now: Date = new Date()): Promise<PolicyAcceptance> {
  const acceptance = { version: POLICY_VERSION, acceptedAt: now.toISOString() };
  await store.set(KEY, acceptance);
  return acceptance;
}

/** Helper for tests: returns true if policy already accepted in the given store. */
export async function isPolicyAccepted(store: Store): Promise<boolean> {
  const a = await getPolicyAcceptance(store);
  return policyAccepted(a);
}
"}

{"path": "src/lib/receiptStore.ts", "content": "// Thin wrapper around Store for the "receipts" collection.
import type { Store, StoredRecord } from './storage/types';
import type { Receipt } from './models';

export async function getAllReceipts(store: Store): Promise<Receipt[]> {
  return store.list<Receipt>('receipts');
}

export async function addReceipt(store: Store, receipt: Receipt): Promise<void> {
  await store.put('receipts', receipt as StoredRecord);
}
"}

{"path": "src/navigation/index.tsx", "content": "import React from 'react';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { NavigationContainer, DefaultTheme } from '@react-navigation/native';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import DashboardScreen from '../screens/DashboardScreen';
import ReceiptsScreen from '../screens/ReceiptsScreen';
import SettingsScreen from '../screens/SettingsScreen';
import PolicyScreen from '../screens/PolicyScreen';
import ReceiptEntryScreen from '../screens/ReceiptEntryScreen';
import { theme } from '../theme';

const Tab = createBottomTabNavigator();
const Stack = createNativeStackNavigator();

// Tab icons are decorative: the tab's label names it (aria-hidden keeps axe from flagging an unlabelled image).
const tabIcon = (name: React.ComponentProps<typeof MaterialCommunityIcons>['name']) =>
  ({ color, size }: { color: string; size: number }) => <MaterialCommunityIcons name={name} color={color} size={size} aria-hidden />;

function Tabs() {
  return (
    <Tab.Navigator
      screenOptions={{
        headerShown: false,
        tabBarActiveTintColor: theme.colors.primary,
        tabBarInactiveTintColor: theme.colors.secondary,
        tabBarStyle: { backgroundColor: theme.colors.surface, height: 64, paddingTop: 6, paddingBottom: 8 },
        tabBarLabelStyle: { fontSize: 12, fontWeight: '500' },
      }}
    >
      <Tab.Screen name="Dashboard" component={DashboardScreen} options={{ tabBarIcon: tabIcon('view-dashboard-outline') }} />
      <Tab.Screen name="Receipts" component={ReceiptsScreen} options={{ tabBarIcon: tabIcon('receipt-outline') }} />
      <Tab.Screen name="Settings" options={{ tabBarIcon: tabIcon('cog-outline') }}>
        {({ navigation }) => <SettingsScreen onViewPolicy={() => navigation.getParent()?.navigate('Policy')} />}
      </Tab.Screen>
    </Tab.Navigator>
  );
}

const navTheme = { ...DefaultTheme, colors: { ...DefaultTheme.colors, background: theme.colors.background, primary: theme.colors.primary } };

/** Main app after the policy is accepted: tabs, plus the policy as a read-only page. */
export default function Navigation() {
  return (
    <NavigationContainer theme={navTheme}>
      <Stack.Navigator>
        <Stack.Screen name="Main" component={Tabs} options={{ headerShown: false }} />
        <Stack.Screen name="Policy" options={{ title: 'Terms and Privacy Policy' }}>
          {() => <PolicyScreen readOnly onAccept={() => {}} />}
        </Stack.Screen>
        <Stack.Screen name="ReceiptEntry" options={{ title: 'Add receipt' }} component={ReceiptEntryScreen} />
        {/* Future modal screens like MileageEntry can be added here */}
      </Stack.Navigator>
    </NavigationContainer>
  );
}
"}

{"path": "src/screens/ReceiptEntryScreen.tsx", "content": "import React, { useState } from 'react';
import { View } from 'react-native';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { PrimaryButton, Screen, FormField, ChoiceField } from '../components/ui';
import { addReceipt } from '../lib/receiptStore';
import { getStore } from '../lib/storage';
import { Receipt, ReceiptType } from '../lib/models';
import { Snackbar } from 'react-native-paper';

export default function ReceiptEntryScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [category, setCategory] = useState('');
  const [type, setType] = useState<ReceiptType>('expense');
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string>('');
  const [snack, setSnack] = useState<string>('');
  const [saving, setSaving] = useState(false);

  const validate = () => {
    if (!amount || isNaN(Number(amount)) || Number(amount) <= 0) return 'Enter a positive amount.';
    if (!date) return 'Select a date.';
    if (!category) return 'Choose a category.';
    if (!type) return 'Select expense or income.';
    return '';
  };

  const onSave = async () => {
    const err = validate();
    if (err) {
      setError(err);
      return;
    }
    setError('');
    setSaving(true);
    const receipt: Receipt = {
      id: `${Date.now()}-${Math.random()}`,
      amount: Number(amount),
      date,
      category,
      type,
      notes,
    };
    try {
      await addReceipt(getStore(), receipt);
      setSnack('Receipt saved');
      setTimeout(() => {
        navigation.navigate('Dashboard');
      }, 0);
    } catch (e) {
      setError('Unable to save receipt. Please try again.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Screen title="Add receipt">
      <View style={{ gap: 12 }}>
        <FormField label="Amount" value={amount} onChangeText={setAmount} keyboardType="numeric" error={error.startsWith('Enter')} />
        <FormField label="Date" value={date} onChangeText={setDate} placeholder="YYYY-MM-DD" error={error.startsWith('Select a date')} />
        <FormField label="Category" value={category} onChangeText={setCategory} error={error.startsWith('Choose a category')} />
        <ChoiceField<ReceiptType>
          label="Type"
          value={type}
          onChange={setType}
          options={[{ value: 'expense', label: 'Expense' }, { value: 'income', label: 'Income' }]}
        />
        <FormField label="Notes" value={notes} onChangeText={setNotes} multiline />
        <PrimaryButton label="Save receipt" onPress={onSave} loading={saving} disabled={saving} />
      </View>
      <Snackbar visible={!!snack} onDismiss={() => setSnack('')} duration={3000}>
        {snack}
      </Snackbar>
    </Screen>
  );
}
"}

