{"path": "src/lib/receiptStore.ts", "content": "// Thin wrapper around Store for the "receipts" collection.
import type { Store, StoredRecord } from './storage/types';
import type { Receipt } from './models';

export async function getAllReceipts(store: Store): Promise<Receipt[]> {
  return store.list<Receipt>('receipts');
}

export async function addReceipt(store: Store, receipt: Receipt): Promise<void> {
  // Cast to StoredRecord to satisfy type constraints.
  await store.put('receipts', receipt as unknown as StoredRecord);
}
"}

{"path": "src/lib/models.ts", "content": "// Core data models for the finance tracker app.

export type ReceiptType = 'expense' | 'income';

export interface Receipt {
  id: string;
  amount: number;
  date: string; // ISO date string (YYYY-MM-DD)
  category: string;
  type: ReceiptType;
  notes: string;
  photoUri?: string;
  [field: string]: unknown; // allow indexing for StoredRecord compatibility
}

export interface MileageEntry {
  id: string;
  date: string; // ISO date
  miles: number;
  purpose: string;
  [field: string]: unknown;
}
"}

