    {
      "severity": "low",
      "file": "src/components/ui/ChoiceField.tsx",
      "issue": "The label for the segmented buttons is rendered as plain `Text` with `accessibilityRole=\"text\"`. It should be associated with the control using `aria-label` or `accessibilityLabel` for better screen‑reader navigation.",
