import { View, Image, StyleSheet } from 'react-native';
import { Button, Text } from 'react-native-paper';
import { space, theme } from '../../theme';
import { pickImageAsync } from '../../lib/photoPicker';

interface Props {
  photoUri?: string;
  onChange: (uri?: string) => void;
}

/** Allows user to pick a photo (camera or library) and returns a stored file URI. */
export default function ReceiptImagePicker({ photoUri, onChange }: Props) {
  const [uri, setUri] = useState<string | undefined>(photoUri);

  const pick = async () => {
    const result = await pickImageAsync();
    if (result) {
      setUri(result);
      onChange(result);
    }
  };

  const remove = () => {
    setUri(undefined);
    onChange(undefined);
  };

  return (
    <View style={styles.container}>
      {uri ? (
        <View style={styles.previewWrap}>
          <Image source={{ uri }} style={styles.preview} accessibilityLabel="Receipt photo" />
          <Button mode="text" onPress={remove} accessibilityLabel="Remove photo">
            Remove photo
          </Button>
        </View>
      ) : (
        <Button mode="outlined" onPress={pick} accessibilityLabel="Add photo">
          Add photo
        </Button>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { marginBottom: space(2) },
  previewWrap: { alignItems: 'center', gap: space(1) },
  preview: { width: 200, height: 200, borderRadius: theme.roundness, backgroundColor: theme.colors.surfaceVariant },
});
"}

{"path": "src/lib/photoPicker.ts", "content": "import * as ImagePicker from 'expo-image-picker';
import { Platform } from 'react-native';

/** Simple wrapper to pick an image from library or camera. Returns the image URI or undefined. */
export async function pickImageAsync(): Promise<string | undefined> {
  // Request permission to access media library (and camera if needed).
  const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();
  if (status !== 'granted') {
    return undefined;
  }
  const result = await ImagePicker.launchImageLibraryAsync({
    allowsEditing: true,
    quality: 0.8,
    mediaTypes: ImagePicker.MediaTypeOptions.Images,
  });
  if (!result.cancelled) {
    return result.uri;
  }
  return undefined;
}
"}

{"path": "src/lib/mileageStore.ts", "content": "// Thin wrapper around Store for the "mileage" collection.
import type { Store, StoredRecord } from './storage/types';
import type { MileageEntry } from './models';

export async function getAllMileageEntries(store: Store): Promise<MileageEntry[]> {
  return store.list<MileageEntry>('mileage');
}

export async function addMileageEntry(store: Store, entry: MileageEntry): Promise<void> {
  await store.put('mileage', entry as unknown as StoredRecord);
}
"}

{"path":"src/lib/mileage.ts","content":"// Mileage calculation helpers.

import type { MileageEntry } from './models';

export const DEFAULT_MILEAGE_RATE = 0.585; // default IRS business rate (USD per mile)

/** Calculate deduction for a single mileage entry. */
export function calculateMileageDeduction(miles: number, rate: number = DEFAULT_MILEAGE_RATE): number {
  return miles * rate;
}

/** Total deduction for a list of entries. */
export function totalMileageDeduction(entries: MileageEntry[], rate: number = DEFAULT_MILEAGE_RATE): number {
  return entries.reduce((sum, e) => sum + calculateMileageDeduction(e.miles, rate), 0);
}
"}

{"path":"src/screens/MileageScreen.tsx","content":"import React, { useEffect, useState } from 'react';
import { ActivityIndicator, FlatList } from 'react-native';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { EmptyState, PrimaryButton, Screen } from '../components/ui';
import { getStore } from '../lib/storage';
import { MileageEntry } from '../lib/models';
import { getAllMileageEntries } from '../lib/mileageStore';
import MileageCard from '../components/ui/MileageCard';

export default function MileageScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [loading, setLoading] = useState(true);
  const [entries, setEntries] = useState<MileageEntry[]>([]);

  const load = async () => {
    setLoading(true);
    const data = await getAllMileageEntries(getStore());
    setEntries(data);
    setLoading(false);
  };

  useEffect(() => {
    const unsubscribe = navigation.addListener('focus', load);
    return unsubscribe;
  }, [navigation]);

  if (loading) {
    return <ActivityIndicator style={{ flex: 1 }} accessibilityLabel="Loading" />;
  }

  const empty = entries.length === 0;

  return (
    <Screen title="Mileage">
      {empty ? (
        <EmptyState
          icon="run-outline"
          title="No mileage logged"
          body="Tap the + button to log your first mileage entry."
          actionLabel="Add mileage"
          onAction={() => navigation.navigate('MileageEntry')}
        />
      ) : (
        <FlatList
          data={entries}
          keyExtractor={(item) => item.id}
          renderItem={({ item }) => <MileageCard entry={item} />}
        />
      )}
    </Screen>
  );
}
"}

{"path": "src/screens/ReceiptEntryScreen.tsx", "content": "import React, { useState } from 'react';
import { View } from 'react-native';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { PrimaryButton, Screen, FormField, ChoiceField } from '../components/ui';
import { addReceipt } from '../lib/receiptStore';
import { getStore } from '../lib/storage';
import { Receipt, ReceiptType } from '../lib/models';
import { Snackbar } from 'react-native-paper';
import { setPendingSnack } from '../lib/uiState';
import ReceiptImagePicker from '../components/ui/ReceiptImagePicker';

export default function ReceiptEntryScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [category, setCategory] = useState('');
  const [type, setType] = useState<ReceiptType>('expense');
  const [notes, setNotes] = useState('');
  const [photoUri, setPhotoUri] = useState<string | undefined>(undefined);
  const [error, setError] = useState<string>('');
  const [saving, setSaving] = useState(false);

  const validate = () => {
    if (!amount || isNaN(Number(amount)) || Number(amount) <= 0) return 'Enter a positive amount.';
    if (!date) return 'Select a date.';
    if (!category) return 'Choose a category.';
    if (!type) return 'Select expense or income.';
    return '';
  };

  const onSave = async () => {
    const err = validate();
    if (err) {
      setError(err);
      return;
    }
    setError('');
    setSaving(true);
    const receipt: Receipt = {
      id: `${Date.now()}-${Math.random()}`,
      amount: Number(amount),
      date,
      category,
      type,
      notes,
      photoUri,
    };
    try {
      await addReceipt(getStore(), receipt);
      setPendingSnack('Receipt saved');
      navigation.navigate('Main', { screen: 'Dashboard' });
    } catch (e) {
      setError('Unable to save receipt. Please try again.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Screen title="Add receipt">
      <View style={{ gap: 12 }}>
        <ReceiptImagePicker photoUri={photoUri} onChange={setPhotoUri} />
        <FormField label="Amount" value={amount} onChangeText={setAmount} keyboardType="numeric" />
        <FormField label="Date" value={date} onChangeText={setDate} placeholder="YYYY-MM-DD" />
        <FormField label="Category" value={category} onChangeText={setCategory} />
        <ChoiceField<ReceiptType>
          label="Type"
          value={type}
          onChange={setType}
          options={[{ value: 'expense', label: 'Expense' }, { value: 'income', label: 'Income' }]}
        />
        <FormField label="Notes" value={notes} onChangeText={setNotes} multiline />
        {error ? <Snackbar visible={true} onDismiss={() => setError('')} duration={3000}>{error}</Snackbar> : null}
        <PrimaryButton label="Save receipt" onPress={onSave} loading={saving} disabled={saving} />
      </View>
    </Screen>
  );
}
"}

