{"path": "src/screens/ReceiptEntryScreen.tsx", "content": "import React, { useState } from 'react';
import { View } from 'react-native';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { PrimaryButton, Screen, FormField, ChoiceField } from '../components/ui';
import { addReceipt } from '../lib/receiptStore';
import { getStore } from '../lib/storage';
import { Receipt, ReceiptType } from '../lib/models';
import { Snackbar } from 'react-native-paper';
import { setPendingSnack } from '../lib/uiState';
import ReceiptImagePicker from '../components/ui/ReceiptImagePicker';
import { v4 as uuidv4 } from 'uuid';

export default function ReceiptEntryScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [category, setCategory] = useState('');
  const [type, setType] = useState<ReceiptType>('expense');
  const [notes, setNotes] = useState('');
  const [photoUri, setPhotoUri] = useState<string | undefined>(undefined);
  const [error, setError] = useState<string>('');
  const [saving, setSaving] = useState(false);

  const validate = () => {
    if (!amount || isNaN(Number(amount)) || Number(amount) <= 0) return 'Enter a positive amount.';
    if (!date) return 'Select a date.';
    if (!category) return 'Choose a category.';
    if (!type) return 'Select expense or income.';
    return '';
  };

  const onSave = async () => {
    const err = validate();
    if (err) {
      setError(err);
      return;
    }
    setError('');
    setSaving(true);
    const receipt: Receipt = {
      id: uuidv4(),
      amount: Number(amount),
      date,
      category,
      type,
      notes,
      photoUri,
    };
    try {
      await addReceipt(getStore(), receipt);
      setPendingSnack('Receipt saved');
      navigation.navigate('Main', { screen: 'Dashboard' });
    } catch (e) {
      setError('Unable to save receipt. Please try again.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Screen title="Add receipt">
      <View style={{ gap: 12 }}>
        <ReceiptImagePicker photoUri={photoUri} onChange={setPhotoUri} />
        <FormField label="Amount" value={amount} onChangeText={setAmount} keyboardType="numeric" />
        <FormField label="Date" value={date} onChangeText={setDate} placeholder="YYYY-MM-DD" />
        <FormField label="Category" value={category} onChangeText={setCategory} />
        <ChoiceField<ReceiptType>
          label="Type"
          value={type}
          onChange={setType}
          options={[{ value: 'expense', label: 'Expense' }, { value: 'income', label: 'Income' }]}
        />
        <FormField label="Notes" value={notes} onChangeText={setNotes} multiline />
        {error ? <Snackbar visible={true} onDismiss={() => setError('')} duration={3000}>{error}</Snackbar> : null}
        <PrimaryButton label="Save receipt" onPress={onSave} loading={saving} disabled={saving} />
      </View>
    </Screen>
  );
}
"}

{"path": "src/screens/TaxSettingsScreen.tsx", "content": "import React, { useEffect, useState } from 'react';
import { View } from 'react-native';
import { PrimaryButton, Screen, FormField } from '../components/ui';
import { getMileageRate, getTaxRate, setMileageRate, setTaxRate, DEFAULT_MILEAGE_RATE, DEFAULT_TAX_RATE } from '../lib/settings';
import { Snackbar } from 'react-native-paper';
import { setPendingSnack } from '../lib/uiState';

export default function TaxSettingsScreen() {
  const [mileageRate, setMileageRateState] = useState<string>('');
  const [taxRate, setTaxRateState] = useState<string>('');
  const [error, setError] = useState<string>('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    (async () => {
      const mr = await getMileageRate();
      const tr = await getTaxRate();
      setMileageRateState(mr.toString());
      setTaxRateState(tr.toString());
    })();
  }, []);

  const validate = () => {
    const mr = Number(mileageRate);
    const tr = Number(taxRate);
    if (isNaN(mr) || mr <= 0) return 'Enter a positive number for mileage rate.';
    if (isNaN(tr) || tr < 0) return 'Enter a non‑negative number for tax rate.';
    return '';
  };

  const onSave = async () => {
    const err = validate();
    if (err) { setError(err); return; }
    setError('');
    setSaving(true);
    try {
      await setMileageRate(Number(mileageRate));
      await setTaxRate(Number(taxRate));
      setPendingSnack('Settings saved');
    } catch (e) {
      setError('Failed to save settings');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Screen title="Tax settings">
      <View style={{ gap: 12 }}>
        <FormField label="Mileage rate ($/mile)" value={mileageRate} onChangeText={setMileageRateState} placeholder={DEFAULT_MILEAGE_RATE.toString()} keyboardType="numeric" />
        <FormField label="Tax rate (%)" value={taxRate} onChangeText={setTaxRateState} placeholder={DEFAULT_TAX_RATE.toString()} keyboardType="numeric" />
        {error ? <Snackbar visible={true} onDismiss={() => setError('')} duration={3000}>{error}</Snackbar> : null}
        <PrimaryButton label="Save" onPress={onSave} loading={saving} disabled={saving} />
      </View>
    </Screen>
  );
}
"}

{"path": "src/navigation/index.tsx", "content": "import React from 'react';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { NavigationContainer, DefaultTheme } from '@react-navigation/native';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import DashboardScreen from '../screens/DashboardScreen';
import ReceiptsScreen from '../screens/ReceiptsScreen';
import SettingsScreen from '../screens/SettingsScreen';
import PolicyScreen from '../screens/PolicyScreen';
import ReceiptEntryScreen from '../screens/ReceiptEntryScreen';
import MileageScreen from '../screens/MileageScreen';
import MileageEntryScreen from '../screens/MileageEntryScreen';
import AppLockScreen from '../screens/AppLockScreen';
import TaxSettingsScreen from '../screens/TaxSettingsScreen';
import ExportScreen from '../screens/ExportScreen';
import { theme } from '../theme';

const Tab = createBottomTabNavigator();
const Stack = createNativeStackNavigator();

// Tab icons are decorative: the tab's label names it (aria-hidden keeps axe from flagging an unlabelled image).
const tabIcon = (name: React.ComponentProps<typeof MaterialCommunityIcons>['name']) =>
  ({ color, size }: { color: string; size: number }) => <MaterialCommunityIcons name={name} color={color} size={size} aria-hidden />;

function Tabs() {
  return (
    <Tab.Navigator
      screenOptions={{
        headerShown: false,
        tabBarActiveTintColor: theme.colors.primary,
        tabBarInactiveTintColor: theme.colors.secondary,
        tabBarStyle: { backgroundColor: theme.colors.surface, height: 64, paddingTop: 6, paddingBottom: 8 },
        tabBarLabelStyle: { fontSize: 12, fontWeight: '500' },
      }}
    >
      <Tab.Screen name="Dashboard" component={DashboardScreen} options={{ tabBarIcon: tabIcon('view-dashboard-outline') }} />
      <Tab.Screen name="Receipts" component={ReceiptsScreen} options={{ tabBarIcon: tabIcon('receipt-outline') }} />
      <Tab.Screen name="Mileage" component={MileageScreen} options={{ tabBarIcon: tabIcon('run') }} />
      <Tab.Screen name="Settings" options={{ tabBarIcon: tabIcon('cog-outline') }}>
        {({ navigation }) => <SettingsScreen onViewPolicy={() => navigation.getParent()?.navigate('Policy')} />}
      </Tab.Screen>
    </Tab.Navigator>
  );
}

const navTheme = { ...DefaultTheme, colors: { ...DefaultTheme.colors, background: theme.colors.background, primary: theme.colors.primary } };

/** Main app after the policy is accepted: tabs, plus the policy as a read‑only page. */
export default function Navigation() {
  return (
    <NavigationContainer theme={navTheme}>
      <Stack.Navigator>
        <Stack.Screen name="Main" component={Tabs} options={{ headerShown: false }} />
        <Stack.Screen name="Policy" options={{ title: 'Terms and Privacy Policy' }}>
          {() => <PolicyScreen readOnly onAccept={() => {}} />}
        </Stack.Screen>
        <Stack.Screen name="ReceiptEntry" options={{ title: 'Add receipt' }} component={ReceiptEntryScreen} />
        <Stack.Screen name="MileageEntry" options={{ title: 'Add mileage' }} component={MileageEntryScreen} />
        <Stack.Screen name="AppLock" options={{ title: 'App lock' }} component={AppLockScreen} />
        <Stack.Screen name="TaxSettings" options={{ title: 'Tax settings' }} component={TaxSettingsScreen} />
        <Stack.Screen name="Export" options={{ title: 'Export data' }} component={ExportScreen} />
      </Stack.Navigator>
    </NavigationContainer>
  );
}
"}

{"path":"src/App.tsx","content":"import React, { useEffect, useState } from 'react';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { StatusBar } from 'expo-status-bar';
import { ActivityIndicator, PaperProvider } from 'react-native-paper';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import Navigation from './navigation';
import { acceptPolicy, getPolicyAcceptance, policyAccepted } from './lib/policy';
import { getStore } from './lib/storage';
import PolicyScreen from './screens/PolicyScreen';
import { theme } from './theme';
import { getAppLockEnabled } from './lib/settings';
import { authenticate } from './lib/appLock';

// Every Paper icon goes through this renderer. Icons sit inside labelled controls, so the glyph is decorative
// and hidden from screen readers (Paper's default web icon is an unlabelled role="img", which fails axe).
const paperSettings = { icon: (props: React.ComponentProps<typeof MaterialCommunityIcons>) => <MaterialCommunityIcons {...props} aria-hidden /> };

type Gate = 'loading' | 'policy' | 'ready';

export default function App() {
  const [gate, setGate] = useState<Gate>('loading');
  const [locked, setLocked] = useState<boolean>(false);

  useEffect(() => {
    getPolicyAcceptance(getStore())
      .then((a) => setGate(policyAccepted(a) ? 'ready' : 'policy'))
      .catch(() => setGate('policy'));
  }, []);

  // Once ready, check app lock setting
  useEffect(() => {
    if (gate === 'ready') {
      (async () => {
        const enabled = await getAppLockEnabled();
        if (enabled) {
          const ok = await authenticate();
          setLocked(!ok);
        }
      })();
    }
  }, [gate]);

  const accept = async () => {
    await acceptPolicy(getStore());
    setGate('ready');
  };

  if (gate === 'loading' || (gate === 'ready' && locked)) {
    return (
      <SafeAreaProvider>
        <PaperProvider theme={theme} settings={paperSettings}>
          <StatusBar style="dark" />
          <ActivityIndicator style={{ flex: 1 }} accessibilityLabel="Loading" />
        </PaperProvider>
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider>
      <PaperProvider theme={theme} settings={paperSettings}>
        <StatusBar style="dark" />
        {gate === 'policy' ? (
          <PolicyScreen onAccept={accept} />
        ) : (
          <Navigation />
        )}
      </PaperProvider>
    </SafeAreaProvider>
  );
}
"}

