    // Load current app lock setting.
    (async () => {
      const v = await getAppLockEnabled();
      setLock(v);
    })();
  }, []);

  const goTo = (screen: string) => {
    const parent = navigation.getParent?.();
    if (parent) {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call, @typescript-eslint/no-explicit-any
      (parent as any).navigate(screen as any);
    } else {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call, @typescript-eslint/no-explicit-any
      (navigation as any).navigate(screen as any);
    }
  };

  const toggleLock = async (value: boolean) => {
    setLock(value);
    await setAppLockEnabled(value);
  };

  const deleteAllData = async () => {
    Alert.alert(
      'Delete all data?',
      'This action cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: async () => {
            const store = getStore();
            await store.clearAll();
          },
        },
      ],
    );
  };

  return (
    <Screen title="Settings">
      <Card mode="outlined" style={{ backgroundColor: theme.colors.surface, marginBottom: 12 }}>
        <SettingSwitch
          label="App lock"
          description="Require biometric authentication on launch"
          value={lock}
          onChange={toggleLock}
        />
      </Card>
      <PrimaryButton label="App lock" variant="secondary" onPress={() => goTo('AppLock')} />
      <PrimaryButton label="Tax settings" variant="secondary" onPress={() => goTo('TaxSettings')} />
      <PrimaryButton label="Export" variant="secondary" onPress={() => goTo('Export')} />
      <PrimaryButton label="Backup & restore" variant="secondary" onPress={() => goTo('Backup')} />
      <PrimaryButton label="Delete all data" variant="secondary" onPress={deleteAllData} />
      <PrimaryButton label="View Terms and Privacy Policy" variant="secondary" onPress={onViewPolicy} />
    </Screen>
  );
}
"}

{"path": "src/screens/ExportScreen.tsx", "content": "import React, { useState } from 'react';
import { View, Text } from 'react-native';
import { ActivityIndicator, Snackbar } from 'react-native-paper';
import { Screen, PrimaryButton } from '../components/ui';
import ExportButton from '../components/ui/ExportButton';
import { generateCsv } from '../lib/exportCsv';
import { generatePdf } from '../lib/exportPdf';
import { useNavigation, NavigationProp } from '@react-navigation/native';

export default function ExportScreen() {
  const [loading, setLoading] = useState(false);
  const [snack, setSnack] = useState<string>('');
  const [message, setMessage] = useState<string>('');
  const navigation = useNavigation<NavigationProp<any>>();

  const showSuccess = () => {
    setMessage('Export ready to share');
    setSnack('Export ready to share');
    // Stay on this screen; UI flow will navigate to Settings later.
  };

  const exportCsv = async () => {
    try {
      setLoading(true);
      await generateCsv();
      showSuccess();
    } catch (e) {
      setSnack('Export failed. Try again.');
    } finally {
      setLoading(false);
    }
  };

  const exportPdf = async () => {
    try {
      setLoading(true);
      await generatePdf();
      showSuccess();
    } catch (e) {
      setSnack('Export failed. Try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Screen title="Export data">
      <View style={{ gap: 12 }}>
        <PrimaryButton label="Back" variant="secondary" onPress={() => navigation.goBack()} />
        <ExportButton label="Export CSV" onPress={exportCsv} />
        <ExportButton label="Export PDF" onPress={exportPdf} />
        {loading && <ActivityIndicator accessibilityLabel="Generating export" />}
        {message ? <Text accessibilityRole="alert" style={{ marginTop: 8 }}>{message}</Text> : null}
      </View>
      <Snackbar visible={!!snack} onDismiss={() => setSnack('')} duration={3000}>
        {snack}
      </Snackbar>
    </Screen>
  );
}
"}

