{"path": "src/lib/backup.ts", "content": "import { getStore } from './storage';
import { getAllReceipts } from './receiptStore';
import { getAllMileageEntries } from './mileageStore';
import { deriveKey, encrypt, decrypt, toBase64, fromBase64, utf8, fromUtf8 } from './crypto';
import type { Receipt, MileageEntry } from './models';
import * as FileSystem from 'expo-file-system';
import * as Sharing from 'expo-sharing';
import { randomBytes } from './crypto';

/** Create an encrypted backup of all data.
 * Returns the file URI of the created backup file.
 */
export async function createBackup(passphrase: string): Promise<string> {
  const store = getStore();
  const receipts: Receipt[] = await getAllReceipts(store);
  const mileage: MileageEntry[] = await getAllMileageEntries(store);
  const payload = JSON.stringify({ receipts, mileage });
  // Generate random 16‑byte salt
  const salt = randomBytes(16);
  const key = deriveKey(passphrase, salt);
  const encrypted = encrypt(key, utf8(payload));
  // prepend salt
  const combined = new Uint8Array(salt.length + encrypted.length);
  combined.set(salt, 0);
  combined.set(encrypted, salt.length);
  const b64 = toBase64(combined);
  const fileUri = (FileSystem as any).cacheDirectory + 'backup.bak';
  await (FileSystem as any).writeAsStringAsync(fileUri, b64, { encoding: (FileSystem as any).EncodingType.UTF8 });
  await Sharing.shareAsync(fileUri, { mimeType: 'application/octet-stream', dialogTitle: 'Backup' });
  return fileUri;
}

/** Restore data from an encrypted backup.
 * Passphrase is used to derive the key; throws on failure.
 */
export async function restoreBackup(fileUri: string, passphrase: string): Promise<void> {
  const b64 = await (FileSystem as any).readAsStringAsync(fileUri, { encoding: (FileSystem as any).EncodingType.UTF8 });
  const combined = fromBase64(b64);
  if (combined.length < 16) throw new Error('Invalid backup file');
  const salt = combined.subarray(0, 16);
  const ciphertext = combined.subarray(16);
  const key = deriveKey(passphrase, salt);
  const decrypted = fromUtf8(decrypt(key, ciphertext));
  const data = JSON.parse(decrypted) as { receipts: Receipt[]; mileage: MileageEntry[] };
  const store = getStore();
  // clear existing data
  await store.clearAll();
  for (const r of data.receipts) {
    await store.put('receipts', { ...(r as any), id: r.id } as any);
  }
  for (const m of data.mileage) {
    await store.put('mileage', { ...(m as any), id: m.id } as any);
  }
}
"}

{"path": "src/screens/DashboardScreen.tsx", "content": "import React, { useEffect, useState } from 'react';
import { ActivityIndicator, Snackbar, Text } from 'react-native-paper';
import { FlatList, View } from 'react-native';
import { useNavigation, useRoute, NavigationProp, RouteProp } from '@react-navigation/native';
import { EmptyState, Screen, SummaryCard } from '../components/ui';
import { getStore } from '../lib/storage';
import { Receipt, MileageEntry } from '../lib/models';
import { getAllReceipts } from '../lib/receiptStore';
import { getAllMileageEntries } from '../lib/mileageStore';
import { computeTotals } from '../lib/finance';
import { totalMileageDeduction } from '../lib/mileage';
import ReceiptCard from '../components/ui/ReceiptCard';
import { consumeSnack } from '../lib/uiState';
import SimpleAddButtons from '../components/ui/SimpleAddButtons';

type DashboardRouteParams = {};

export default function DashboardScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const route = useRoute<RouteProp<Record<string, DashboardRouteParams>, string>>();
  const [loading, setLoading] = useState(true);
  const [receipts, setReceipts] = useState<Receipt[]>([]);
  const [mileageEntries, setMileageEntries] = useState<MileageEntry[]>([]);
  const [mileageDeduction, setMileageDeduction] = useState<number>(0);
  const [snack, setSnack] = useState<string>('');

  const load = async () => {
    setLoading(true);
    const recs = await getAllReceipts(getStore());
    const miles = await getAllMileageEntries(getStore());
    setReceipts(recs);
    setMileageEntries(miles);
    // Compute mileage deduction asynchronously
    const deduction = await totalMileageDeduction(miles);
    setMileageDeduction(deduction);
    setLoading(false);
    const pending = consumeSnack();
    if (pending) setSnack(pending);
  };

  useEffect(() => {
    const unsubscribe = navigation.addListener('focus', load);
    return unsubscribe;
  }, [navigation]);

  if (loading) {
    return <ActivityIndicator style={{ flex: 1 }} accessibilityLabel="Loading" />;
  }

  const totals = computeTotals(receipts);

  const empty = receipts.length === 0 && mileageEntries.length === 0;

  return (
    <Screen title="Dashboard" wide>
      {empty ? (
        <EmptyState
          icon="inbox-outline"
          title="Nothing here yet"
          body="Add a receipt or mileage entry to start tracking your finances."
        />
      ) : (
        <View style={{ gap: 16 }}>
          <View style={{ flexDirection: 'row', gap: 8, flexWrap: 'wrap' }}>
            <SummaryCard label="Income" value={`$${totals.income.toFixed(2)}`} />
            <SummaryCard label="Expenses" value={`$${totals.expenses.toFixed(2)}`} />
            <SummaryCard label="Mileage deduction" value={`$${mileageDeduction.toFixed(2)}`} />
            <SummaryCard label="Estimated tax" value="$0.00" />
          </View>
          <Text variant="titleMedium" style={{ marginTop: 8, marginBottom: 4 }}>Recent activity</Text>
          <FlatList
            data={receipts.slice(0, 5)}
            keyExtractor={(item) => item.id}
            renderItem={({ item }) => <ReceiptCard receipt={item} />}
          />
        </View>
      )}
      <Snackbar visible={!!snack} onDismiss={() => setSnack('')} duration={3000}>
        {snack}
      </Snackbar>
      <SimpleAddButtons />
    </Screen>
  );
}
"}

{"path": "src/navigation/index.tsx", "content": "import React from 'react';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { NavigationContainer, DefaultTheme } from '@react-navigation/native';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import DashboardScreen from '../screens/DashboardScreen';
import ReceiptsScreen from '../screens/ReceiptsScreen';
import SettingsScreen from '../screens/SettingsScreen';
import PolicyScreen from '../screens/PolicyScreen';
import ReceiptEntryScreen from '../screens/ReceiptEntryScreen';
import MileageScreen from '../screens/MileageScreen';
import MileageEntryScreen from '../screens/MileageEntryScreen';
import AppLockScreen from '../screens/AppLockScreen';
import TaxSettingsScreen from '../screens/TaxSettingsScreen';
import ExportScreen from '../screens/ExportScreen';
import BackupScreen from '../screens/BackupScreen';
import RestoreScreen from '../screens/RestoreScreen';
import { theme } from '../theme';

const Tab = createBottomTabNavigator();
const Stack = createNativeStackNavigator();
const SettingsStack = createNativeStackNavigator();

// Tab icons are decorative: the tab's label names it (aria-hidden keeps axe from flagging an unlabelled image).
const tabIcon = (name: React.ComponentProps<typeof MaterialCommunityIcons>['name']) =>
  ({ color, size }: { color: string; size: number }) => <MaterialCommunityIcons name={name} color={color} size={size} aria-hidden />;

function SettingsStackScreen() {
  return (
    <SettingsStack.Navigator>
      <SettingsStack.Screen name="SettingsMain" component={SettingsScreen} options={{ headerShown: false }} />
      <SettingsStack.Screen name="Export" component={ExportScreen} options={{ title: 'Export data' }} />
      <SettingsStack.Screen name="Backup" component={BackupScreen} options={{ title: 'Backup & restore' }} />
      <SettingsStack.Screen name="Restore" component={RestoreScreen} options={{ title: 'Restore backup' }} />
      <SettingsStack.Screen name="AppLock" component={AppLockScreen} options={{ title: 'App lock' }} />
      <SettingsStack.Screen name="TaxSettings" component={TaxSettingsScreen} options={{ title: 'Tax settings' }} />
    </SettingsStack.Navigator>
  );
}

function Tabs() {
  return (
    <Tab.Navigator
      screenOptions={{
        headerShown: false,
        tabBarActiveTintColor: theme.colors.primary,
        tabBarInactiveTintColor: theme.colors.secondary,
        tabBarStyle: { backgroundColor: theme.colors.surface, height: 64, paddingTop: 6, paddingBottom: 8 },
        tabBarLabelStyle: { fontSize: 12, fontWeight: '500' },
      }}
    >
      <Tab.Screen name="Dashboard" component={DashboardScreen} options={{ tabBarIcon: tabIcon('view-dashboard-outline') }} />
      <Tab.Screen name="Receipts" component={ReceiptsScreen} options={{ tabBarIcon: tabIcon('receipt-outline') }} />
      <Tab.Screen name="Mileage" component={MileageScreen} options={{ tabBarIcon: tabIcon('run') }} />
      <Tab.Screen name="Settings" component={SettingsStackScreen} options={{ tabBarIcon: tabIcon('cog-outline') }} />
    </Tab.Navigator>
  );
}

const navTheme = { ...DefaultTheme, colors: { ...DefaultTheme.colors, background: theme.colors.background, primary: theme.colors.primary } };

/** Main app after the policy is accepted: tabs, plus the policy as a read‑only page. */
export default function Navigation() {
  return (
    <NavigationContainer theme={navTheme}>
      <Stack.Navigator>
        <Stack.Screen name="Main" component={Tabs} options={{ headerShown: false }} />
        <Stack.Screen name="Policy" options={{ title: 'Terms and Privacy Policy' }}>
          {() => <PolicyScreen readOnly onAccept={() => {}} />}
        </Stack.Screen>
        <Stack.Screen name="ReceiptEntry" options={{ title: 'Add receipt' }} component={ReceiptEntryScreen} />
        <Stack.Screen name="MileageEntry" options={{ title: 'Add mileage' }} component={MileageEntryScreen} />
        {/* Other modal screens can be added here if needed */}
      </Stack.Navigator>
    </NavigationContainer>
  );
}
"}

